"""Card disambiguation tools."""

from __future__ import annotations

import re

# The tool loader puts the agent root on sys.path while importing this module,
# so shared code under lib/ is importable from any tool location.
from lib.wallet_loader import load_wallet_data

from rasa.mantle.tools.decorator import ToolContext, tool
from rasa.mantle.tools.result import ToolResult

_wallet = load_wallet_data()
_CARDS = _wallet.CARDS


def _card_list_display_text(cards: list[dict]) -> str:
    """Customer-facing lines for utter templates (name + last four)."""
    return "\n".join(f"- {card['label']}" for card in cards)


def _normalize(text: str) -> str:
    """Lower-case *text* and strip everything but letters and digits."""
    return re.sub(r"[^a-z0-9]", "", text.lower())


def _last_four(text: str) -> str | None:
    """Return the last 4-digit group in *text*, or ``None`` when there is none."""
    groups = re.findall(r"\d{4}", text)
    return groups[-1] if groups else None


def _card_by_label(card_label: str | None, card_list: list[dict]) -> dict | None:
    """Return the single card *card_label* refers to, tolerant of phrasing."""
    query = (card_label or "").strip()
    if not query:
        return None

    for card in card_list:
        if card.get("label") == query:
            return card

    query_digits = _last_four(query)
    if query_digits:
        digit_matches = [
            card
            for card in card_list
            if _last_four(str(card.get("label", ""))) == query_digits
        ]
        if len(digit_matches) == 1:
            return digit_matches[0]

    query_norm = _normalize(query)
    if query_norm:
        name_matches = [
            card
            for card in card_list
            if query_norm in _normalize(str(card.get("label", "")))
            or _normalize(str(card.get("label", ""))) in query_norm
        ]
        if len(name_matches) == 1:
            return name_matches[0]

    return None


@tool(description="Load the customer's cards. Call this first.")
async def action_fetch_accounts(context: ToolContext = None) -> ToolResult:
    display_text = _card_list_display_text(_CARDS)
    context.memory.set("card_list", _CARDS)
    context.memory.set("card_list_display_text", display_text)
    return ToolResult(
        llm_response={
            "cards": _CARDS,
            "card_count": len(_CARDS),
            "card_list_display_text": display_text,
        }
    )


@tool(description="Clear the previous card choice before selecting a card.")
async def clear_selected_card(context: ToolContext = None) -> ToolResult:
    context.memory.set("selected_card_id", None)
    context.memory.set("selected_card_label", None)
    context.memory.set("selected_card_eligible", None)
    return ToolResult(llm_response={"ok": True})


@tool(description="Memory validation tool: resolve card label to card id.")
async def run_after_setting_selected_card_label(
    context: ToolContext = None,
) -> ToolResult:
    card_label = context.memory.get("selected_card_label")
    card_list = context.memory.get("card_list") or []
    matched = _card_by_label(card_label, card_list)

    if matched is None:
        context.memory.set("selected_card_id", None)
        context.memory.set("selected_card_eligible", None)
        return ToolResult(
            llm_response={
                "ok": False,
                "error": "card_not_found",
                "hint": "List the cards and ask which one applies.",
            }
        )

    selected_id = str(matched["id"])
    context.memory.set("selected_card_id", selected_id)
    context.memory.set("selected_card_label", matched["label"])
    context.memory.set("selected_card_eligible", bool(matched.get("eligible", True)))
    return ToolResult(
        llm_response={
            "ok": True,
            "selected_card_id": selected_id,
            "selected_card_label": matched["label"],
        }
    )
